```json
{
  "root_causes": [
    {
      "service": "ts-train-food-service",
      "fault_kind": "application_method_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, count(*) n, round(approx_quantile(duration,0.5)/1e6,1) p50_ms, round(approx_quantile(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-train-food-service' AND span_name IN ('TrainFoodController.getTrainFoodOfTrip','TrainFoodRepository.findByTripId','SELECT ts.train_food') GROUP BY 1 ORDER BY 1",
          "claim": "getTrainFoodOfTrip self-time is a flat ~1714ms while its DB child spans stay around 2ms in the abnormal period."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, count(*) n, round(approx_quantile(duration,0.95)/1e6,1) p95_ms FROM normal_traces WHERE service_name='ts-train-food-service' AND span_name='TrainFoodController.getTrainFoodOfTrip' GROUP BY 1",
          "claim": "In the normal period the same method has p95 of about 4.7ms, so the slowdown is new."
        },
        {
          "kind": "metric",
          "sql": "SELECT service_name, metric, round(avg(value),4) avgv FROM abnormal_metrics WHERE service_name='ts-train-food-service' AND metric IN ('k8s.pod.cpu.usage','container.memory.working_set') GROUP BY 1,2",
          "claim": "Train-food pod CPU and memory stay low and unsaturated during the slowdown, so the delay is inside the method, not resource exhaustion."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-train-food-service",
      "to": "ts-food-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) n, round(approx_quantile(duration,0.5)/1e6,1) p50_ms FROM abnormal_traces WHERE (service_name='ts-food-service' AND span_name IN ('FoodController.getAllFood','GET')) GROUP BY 1,2 ORDER BY 2",
          "claim": "ts-food-service getAllFood and its client GET to train-food both take about 1718ms, with almost no own time."
        }
      ]
    },
    {
      "from": "ts-food-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) n, round(approx_quantile(duration,0.5)/1e6,1) p50_ms, round(approx_quantile(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE span_name='GET /api/v1/foodservice/foods/{date}/{startStation}/{endStation}/{tripId}' AND service_name='ts-ui-dashboard' GROUP BY 1,2",
          "claim": "ts-ui-dashboard food endpoint rises from about 30ms p95 in normal to about 1742ms p95 in abnormal."
        }
      ]
    }
  ]
}
```

